mapper.select:
SELECT s.id, s.student_id, s.course_id, s.score, s.term, s.exam_time, st.name as studentName, c.course_name as courseName FROM scores s INNER JOIN students st ON s.student_id = st.id INNER JOIN courses c ON s.course_id = c.id WHERE st.class_id = #{classId}
AND s.term = #{term}
ORDER BY s.student_id, s.course_id, s.exam_time DESC
